function c4Winner(b){for(var r=0;r<6;r++)for(var c=0;c<7;c++){var p=b[r][c];if(!p)continue;for(var dr=-1;dr<=1;dr++)for(var dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;var ok=true;for(var k=1;k<4;k++){var rr=r+dr*k,cc=c+dc*k;if(rr<0||rr>=6||cc<0||cc>=7||b[rr][cc]!==p){ok=false;break;}}if(ok)return p;}}return b[0].every(Boolean)?3:0;}
