function sortPlayMoveFx(){
 var screen=root&&root.querySelector(".mg-sort-screen"),move=s&&s.lastMove;
 if(!screen||!move||Date.now()-move.at>1200)return;
 var a=screen.querySelector('.mg-sort-tube[data-i="'+move.from+'"]'),b=screen.querySelector('.mg-sort-tube[data-i="'+move.to+'"]');
 if(!a||!b)return;
 var source=a.querySelector(".mg-ball-stack"),dest=b.querySelector(".mg-ball-stack");
 var sr=source?source.getBoundingClientRect():a.getBoundingClientRect();
 var destBalls=dest?Array.from(dest.querySelectorAll(".mg-ball")).slice(-move.count):[];
 var color=s.tubes[move.to][s.tubes[move.to].length-1],colors={r:"#ff5268",g:"#50f59a",b:"#55baff",y:"#ffdb54",p:"#d78aff",o:"#ff9b48",c:"#5af0e9",m:"#ff75b9",w:"#fff0fb",l:"#b5f5ff"};
 destBalls.forEach(function(target,k){
  var tr=target.getBoundingClientRect(),ghost=target.cloneNode(true);
  var startX=sr.left+sr.width/2-tr.width/2,startY=sr.top+9+(move.count-1-k)*Math.min(17,tr.height*.42);
  ghost.classList.remove("sort-land");ghost.style.cssText+=";position:fixed!important;left:"+startX+"px!important;top:"+startY+"px!important;width:"+tr.width+"px!important;height:"+tr.height+"px!important;margin:0!important;z-index:100200!important;pointer-events:none!important;transition:transform .46s cubic-bezier(.18,.8,.25,1.15),filter .46s ease!important;filter:brightness(1.5) drop-shadow(0 0 9px "+(colors[color]||"#fff")+")!important";
  document.body.appendChild(ghost);
  var dx=tr.left-startX,dy=tr.top-startY;
  requestAnimationFrame(function(){requestAnimationFrame(function(){ghost.style.transform="translate("+dx+"px,"+dy+"px) scale(1.05)";});});
  setTimeout(function(){ghost.remove();},650+k*95);
 });
 var srn=screen.getBoundingClientRect(),x=(sr.left+sr.right)/2-srn.left,y=(sr.top+sr.bottom)/2-srn.top;
 for(var k=0;k<Math.min(22,move.count*6+5);k++){var dot=document.createElement("i");dot.className="sort-fx";dot.style.left=x+"px";dot.style.top=y+"px";dot.style.setProperty("--fx-color",colors[color]||"#ffe16a");dot.style.setProperty("--fx-x",(Math.random()*100-50)+"px");dot.style.setProperty("--fx-y",(Math.random()*-100-18)+"px");screen.appendChild(dot);(function(el){setTimeout(function(){el.remove();},750);})(dot);}
 if(s.done){var fx=document.createElement("div");fx.className="sort-win-fx";for(var n=0;n<54;n++){var bit=document.createElement("i");bit.style.left=(Math.random()*100)+"%";bit.style.setProperty("--confetti",["#ffdf4d","#ff4f86","#4eeaff","#73f58b","#c78bff"][n%5]);bit.style.setProperty("--delay",(Math.random()*.65)+"s");fx.appendChild(bit);}screen.appendChild(fx);}
}
function sortAction(a,i){
 if(a==="sort-back"){close();return;}
 if(a==="sort-settings"){s.msg="Ayarlar";return;}
 if(a==="sort-theme"){s.theme=(s.theme||0)+1;return;}
 if(a==="sort-retry"){sortInit();return;}
 if(a==="sort-next"&&s.done){if(s.level<200)localStorage.setItem(sortKey(),String(s.level+1));else localStorage.setItem(sortKey(),"200");sortInit();s.msg=s.level===200?"200 seviyeyi bitirdin! Renk ustasısın.":"Seviye "+(s.level-1)+" tamamlandı. Daha zor seviye açıldı.";return;}
 if(a==="sort-undo"){if(s.history.length){var prev=s.history.pop();s.tubes=prev.tubes;s.moves=prev.moves;s.done=false;s.sel=-1;s.hint=null;s.msg="Son hamle geri alındı.";}return;}
 if(a==="sort-hint"){var found=null;for(var x=0;x<s.tubes.length&&!found;x++){var f=s.tubes[x];if(!f.length)continue;var col=f[f.length-1];for(var y=0;y<s.tubes.length;y++){var t=s.tubes[y];if(x!==y&&t.length<s.cap&&(!t.length||t[t.length-1]===col)){found=[x,y];break;}}}s.hint=found;s.msg=found?"Işıklı tüpler arasında taşıma yap.":"Şu an uygun hamle yok.";return;}
 if(a==="sort-extra"){if(s.extraTubes<3){s.tubes.push([]);s.extraTubes++;s.msg="Ek tüp açıldı.";}else s.msg="Bu seviyede ek tüp sınırına ulaştın.";return;}
 if(a!=="sort-tube"||s.done)return;
 if(s.sel<0){if(s.tubes[i].length)s.sel=i;else s.msg="Önce dolu bir tüp seç.";return;}
 if(s.sel===i){s.sel=-1;return;}
 var from=s.tubes[s.sel],to=s.tubes[i],ball=from[from.length-1];
 if(ball&&to.length<s.cap&&(!to.length||to[to.length-1]===ball)){
  sortRemember();
  var transfer=1;
  /* Aynı renkteki üst küre grubu tek hamlede aktarılır. */
  while(transfer<from.length&&from[from.length-1-transfer]===ball)transfer++;
  transfer=Math.min(transfer,s.cap-to.length);
  s.lastMove={from:s.sel,to:i,count:transfer,at:Date.now()};
  for(var move=0;move<transfer;move++)to.push(from.pop());
  s.moves++;s.msg=transfer>1?transfer+" aynı renk top birlikte taşındı.":"Güzel hamle!";
  s.hint=null;
  if(sortWon()){s.done=true;s.msg="Harika! Seviye "+s.level+" tamamlandı. Sonraki seviyeye geçebilirsin.";localStorage.setItem(sortKey(),String(Math.min(200,s.level+1)));}
 }else s.msg="Bu renk buraya taşınamaz.";
 s.sel=-1;
}

