function bgInit(){var b=Array(24).fill(0);b[0]=2;b[11]=5;b[16]=3;b[18]=5;b[23]=-2;b[12]=-5;b[7]=-3;b[5]=-5;s={b:b,bar:[0,0],off:[0,0],dice:[],selected:-1,done:false,turn:0,msg:"Zar at ve taşlarını topla.",moves:0};bgRoll();}
function bgRoll(){var a=1+Math.floor(Math.random()*6),b=1+Math.floor(Math.random()*6);s.dice=a===b?[a,a,a,a]:[a,b];s.msg="Zarlar: "+a+" ve "+b+". Hamle seçeneklerinden birini seç.";s.selected=-1;}
function bgHome(side){if(s.bar[side]>0)return false;return side===0?s.b.slice(0,18).every(v=>v<=0):s.b.slice(6,24).every(v=>v>=0);}
function bgMoves(side,die){var out=[],bar=s.bar[side];if(bar>0){var to=side===0?24-die:die-1;if(to>=0&&to<24&&(side===0?s.b[to]>=-1:s.b[to]<=1))out.push({from:-1,to:to,die:die,hit:Math.abs(s.b[to])===1,enter:true});return out;}for(var from=0;from<24;from++){if(side===0?s.b[from]<=0:s.b[from]>=0)continue;var to=side===0?from+die:from-die,off=to<0||to>23;if(off){if(!bgHome(side))continue;var far=false;if(side===0){for(var q=from+1;q<24;q++)if(s.b[q]>0)far=true;if(to>23&&far)continue;}else{for(var q=0;q<from;q++)if(s.b[q]<0)far=true;if(to<0&&far)continue;}out.push({from:from,to:-2,die:die,hit:false,off:true});}else if(side===0?s.b[to]>=-1:s.b[to]<=1)out.push({from:from,to:to,die:die,hit:Math.abs(s.b[to])===1,enter:false});}return out;}
function bgAllMoves(side){var a=[];s.dice.forEach(function(d){bgMoves(side,d).forEach(function(m){a.push(m);});});return a;}
function bgApply(side,m){if(m.enter){s.bar[side]--;if(m.hit){if(side===0){s.b[m.to]=0;s.bar[1]++;}else{s.b[m.to]=0;s.bar[0]++;}}if(side===0)s.b[m.to]++;else s.b[m.to]--;}else{if(side===0)s.b[m.from]--;else s.b[m.from]++;if(m.off){s.off[side]++;}else{if(m.hit){if(side===0){s.b[m.to]=0;s.bar[1]++;}else{s.b[m.to]=0;s.bar[0]++;}}if(side===0)s.b[m.to]++;else s.b[m.to]--;}}var ix=s.dice.indexOf(m.die);if(ix>=0)s.dice.splice(ix,1);s.moves++;if(s.off[side]>=15){s.done=true;s.winner=side;s.msg=side===0?"Tavlayı kazandın!":"Bot tavlayı kazandı.";} }
function bgScore(m,side){var score=m.off?100:m.hit?35:0;if(m.to>=0){score+=side===0?m.to*.35:(23-m.to)*.35;if(Math.abs(s.b[m.to])===1)score+=8;}if(m.from>=0){var left=side===0?23-m.from:m.from;score+=Math.max(0,6-left)*2;}return score+Math.random();}
function bgBot(){var guard=0;while(s.dice.length&&!s.done&&guard++<4){var options=bgAllMoves(1);if(!options.length){s.dice=[];break;}options.sort((a,b)=>bgScore(b,1)-bgScore(a,1));bgApply(1,options[0]);}if(s.done)return;s.turn=0;bgRoll();if(!bgAllMoves(0).length){s.turn=1;s.msg="Bu zarlarla hamlen yok. Bot oynuyor…";bgBot();return;}s.msg="Sıra sende. Zarına uygun hamleyi seç.";}
function bgMoveLabel(m){var a=m.from===-1?"Bar":String(m.from+1),b=m.off?"Topla":String(m.to+1);return a+" → "+b+"  (zar "+m.die+")";}
function bgHtml(){var h=stats(["Senin taşın: "+s.off[0]+"/15","Bot: "+s.off[1]+"/15","Bar: "+s.bar[0]+" · "+s.bar[1]])+'<div class="mg-card">Sen taşlarını 1’den 24’e, bot ters yönde ilerletir. İki rakip taşın bulunduğu nokta kapalıdır. Tek taş kırılır ve bara gider.</div><div class="mg-backgammon">';h+='<div class="mg-bg-row">';for(var i=23;i>=12;i--)h+=bgPoint(i);h+='</div><div class="mg-bg-middle">ZARLAR · '+(s.dice.join(" · ")||"—")+'</div><div class="mg-bg-row">';for(var j=0;j<12;j++)h+=bgPoint(j);h+='</div></div><div class="mg-msg">'+s.msg+'</div>';var moves=s.turn===0&&!s.done?bgAllMoves(0):[];if(moves.length){h+='<div class="mg-bg-moves">';moves.forEach(function(m){h+='<button class="mg-btn" data-mg="bg-move" data-from="'+m.from+'" data-to="'+m.to+'" data-die="'+m.die+'">'+bgMoveLabel(m)+'</button>';});h+='</div>';}if(s.done)h+='<div class="mg-big">'+(s.winner===0?"🏆":"🎲")+'</div>';h+='<button class="mg-btn alt" data-mg="bg-reset">Yeni oyun</button>';return h;}
function bgPoint(i){var v=s.b[i],count=Math.abs(v),owner=v>0?"you":v<0?"bot":"empty";return '<button class="mg-bg-point '+owner+'" data-mg="bg-point" data-i="'+i+'"><small>'+(i+1)+'</small><b>'+(count?count:"·")+'</b></button>';}
function bgPlayTurn(){if(s.done)return;if(!s.dice.length||!bgAllMoves(0).length){s.turn=1;s.msg="Bot oynuyor…";bgBot();return;}s.msg="Kalan zar: "+s.dice.join(", ")+" · Geçerli hamleni seç.";}


function snakeInit(){var start=8*16+7;s={snake:[start,start-1,start-2],dir:"right",nextDir:"right",food:snakeFood([start,start-1,start-2]),score:0,best:Number(localStorage.getItem("arenaSnakeBest")||0),speed:180,running:false,done:false,msg:"Başla. Yön tuşlarıyla veya ekranı kaydırarak hareket et."};}
function snakeFood(body){var free=[];for(var i=0;i<256;i++)if(body.indexOf(i)<0)free.push(i);return free.length?free[Math.floor(Math.random()*free.length)]:-1;}
function snakeTurn(d){var opposite={up:"down",down:"up",left:"right",right:"left"};if(opposite[d]!==s.dir)s.nextDir=d;}
function snakeTick(){if(!s||id!=="snake"||!s.running||s.done)return;s.dir=s.nextDir;var head=s.snake[0],r=Math.floor(head/16),c=head%16,nr=r+(s.dir==="down"?1:s.dir==="up"?-1:0),nc=c+(s.dir==="right"?1:s.dir==="left"?-1:0),next=nr*16+nc,food=next===s.food,body=food?s.snake:s.snake.slice(0,-1);if(nr<0||nr>=16||nc<0||nc>=16||body.indexOf(next)>=0){s.running=false;s.done=true;s.msg="Oyun bitti! Puanın: "+s.score;if(s.score>s.best){s.best=s.score;localStorage.setItem("arenaSnakeBest",String(s.best));}render();return;}s.snake.unshift(next);if(food){s.score+=10;s.food=snakeFood(s.snake);s.speed=Math.max(65,180-Math.floor(s.score/50)*8);if(s.food<0){s.done=true;s.running=false;s.msg="Tahtayı tamamen doldurdun! Muhteşem!";}}else s.snake.pop();render();if(s.running)later(snakeTick,s.speed);}
function snakeStart(){if(s.done)snakeInit();if(s.running)return;s.running=true;s.msg="Yılan hareket ediyor!";later(snakeTick,s.speed);}
function snakeHtml(){var body=s.snake,head=body[0],h=stats(["Puan: "+s.score,"Rekor: "+s.best,"Hız: "+(190-s.speed)])+'<div class="mg-snake-board">';for(var i=0;i<256;i++){var cls=i===head?"head":body.indexOf(i)>=0?"body":i===s.food?"food":"empty";h+='<span class="'+cls+'">'+(i===s.food?"●":"")+'</span>';}h+='</div><div class="mg-msg">'+s.msg+'</div>';if(!s.running&&!s.done)h+='<button class="mg-btn gold" data-mg="snake-start">Başla</button>';h+='<div class="mg-snake-pad"><span></span><button data-mg="snake-up">↑</button><span></span><button data-mg="snake-left">←</button><button data-mg="snake-down">↓</button><button data-mg="snake-right">→</button></div><button class="mg-btn alt" data-mg="snake-reset">Yeni oyun</button>';return h;}


/* Two offline color puzzle games, each with 20 saved progressive levels. */
function cmLevel(){return Math.max(1,Math.min(20,Number(localStorage.getItem("arenaColorMemoryLevel")||1)));}
function cmInit(){var level=cmLevel(),palette=["🔴","🔵","🟡","🟢","🟣","🟠"],len=Math.min(12,3+Math.floor((level-1)*0.48));s={level:level,palette:palette,seq:Array.from({length:len},()=>Math.floor(Math.random()*Math.min(6,3+Math.floor((level-1)/4)))),input:[],showing:true,done:false,won:false,msg:"Renk dizisini izle ve aynı sırayla dokun.",flash:-1};}
function cmHtml(){var h=stats(["Seviye "+s.level+"/20","Dizi: "+s.seq.length+" renk","Doğru: "+s.input.length+"/"+s.seq.length]);h+='<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-width:360px;margin:18px auto">';s.palette.forEach(function(c,i){var active=s.flash===i;h+='<button data-mg="cm-color" data-i="'+i+'" style="min-height:88px;border-radius:20px;border:2px solid '+(active?'#fff':'#527bb1')+';background:'+(active?'#f6c34c':'linear-gradient(145deg,#173c68,#091a35)')+';font-size:38px;box-shadow:'+(active?'0 0 24px #f6c34c':'0 8px 18px #0008')+'" '+(s.showing||s.done?'disabled':'')+'>'+c+'</button>';});h+='</div><div class="mg-msg">'+s.msg+'</div>';if(s.done&&s.won)h+='<button class="mg-btn gold" data-mg="cm-next">Sonraki seviye →</button>';h+='<button class="mg-btn alt" data-mg="cm-replay">Tekrar göster</button>';return h;}
function cmShow(){s.showing=true;s.input=[];s.flash=-1;s.msg="Diziyi dikkatle izle…";render();var n=0;function tick(){if(!s||id!=="colorMemory")return;if(n>0)s.flash=-1;if(n>=s.seq.length){s.showing=false;s.msg="Şimdi sırayı sen tekrarla.";render();return;}s.flash=s.seq[n++];render();later(tick,520);}later(tick,350);}
function cmAction(a,i){if(a==="cm-replay"){cmShow();return;}if(a==="cm-next"&&s.done&&s.won){if(s.level<20)localStorage.setItem("arenaColorMemoryLevel",String(s.level+1));cmInit();cmShow();return;}if(a!=="cm-color"||s.showing||s.done)return;s.input.push(i);if(i!==s.seq[s.input.length-1]){s.done=true;s.won=false;s.msg="Dizi bozuldu. Tekrar gösterip yeniden dene.";return;}if(s.input.length===s.seq.length){s.done=true;s.won=true;if(s.level<20)localStorage.setItem("arenaColorMemoryLevel",String(s.level+1));s.msg=s.level===20?"20 seviyeyi tamamladın! Usta oldun.":"Harika! Seviye tamamlandı. Sonraki seviye açıldı.";}else s.msg="Doğru! Devam et.";}
function chLevel(){return Math.max(1,Math.min(20,Number(localStorage.getItem("arenaColorHuntLevel")||1)));}
function chInit(){var level=chLevel(),size=Math.min(8,3+Math.floor((level-1)/3)),total=size*size,target=Math.floor(Math.random()*total),hue=Math.floor(Math.random()*360),diff=Math.max(5,34-level*1.35);s={level:level,size:size,target:target,hue:hue,diff:diff,done:false,won:false,msg:"Diğerlerinden farklı renkteki kareyi bul."};}
function chHtml(){var h=stats(["Seviye "+s.level+"/20","Izgara "+s.size+"×"+s.size,"Renk farkı "+Math.round(s.diff)]);h+='<div style="display:grid;grid-template-columns:repeat('+s.size+',minmax(0,1fr));gap:5px;width:min(100%,390px);margin:18px auto">';for(var i=0;i<s.size*s.size;i++){var alt=i===s.target,light=alt?Math.max(18,50-s.level*.6):50;h+='<button data-mg="ch-cell" data-i="'+i+'" aria-label="Renk karesi" style="aspect-ratio:1;min-width:0;border:1px solid #ffffff40;border-radius:9px;background:hsl('+s.hue+',65%,'+(light+(alt?s.diff/2:0))+'%)" '+(s.done?'disabled':'')+'></button>';}h+='</div><div class="mg-msg">'+s.msg+'</div>';if(s.done&&s.won)h+='<button class="mg-btn gold" data-mg="ch-next">Sonraki seviye →</button>';h+='<button class="mg-btn alt" data-mg="ch-retry">Yenile</button>';return h;}
function chAction(a,i){if(a==="ch-retry"){chInit();return;}if(a==="ch-next"&&s.done&&s.won){if(s.level<20)localStorage.setItem("arenaColorHuntLevel",String(s.level+1));chInit();return;}if(a!=="ch-cell"||s.done)return;s.done=true;s.won=i===s.target;if(s.won){if(s.level<20)localStorage.setItem("arenaColorHuntLevel",String(s.level+1));s.msg=s.level===20?"20 seviyeyi tamamladın! Renk ustasısın.":"Doğru renk! Sonraki seviye açıldı.";}else s.msg="Bu kare değil. Tekrar dene.";}

function render(){var h="";if(id==="snake")h=snakeHtml();else if(id==="backgammon")h=bgHtml();else if(id==="nonogram")h=nonoHtml();else if(id==="checkers")h=damaHtml();else if(id==="wordle")h=wordleHtml();else if(id==="game2048")h=game2048Html();else if(id==="miniSudoku")h=sudHtml();else if(id==="memory")h=memHtml();else if(id==="colorSort"||id==="liquidSort"||id==="ballSort")h=sortHtml();else if(id==="reflexTap")h=reflexHtml();else if(id==="wordScramble")h=wordHtml();else if(id==="mathSprint")h=mathHtml();else if(id==="ticTacToe")h=xoHtml();else if(id==="connectFour")h=c4Html();else if(id==="minesweeper")h=mineHtml();else if(id==="colorMemory")h=cmHtml();else if(id==="colorHunt")h=chHtml();shell(h);if(id==="mathSprint"&&s&&s.running){setTimeout(function(){var f=root&&root.querySelector("#mg-math");if(f)f.focus({preventScroll:true});},60);}if(id==="colorSort"||id==="liquidSort"||id==="ballSort")sortWinterParticles();var cv=root.querySelector(".mg-3d-canvas");if(cv&&window.Arena3D)window.Arena3D.mount(cv,id);var st=root.querySelector("[data-mg=audio-music]"),se=root.querySelector("[data-mg=audio-sfx]");if(st&&window.Arena3D){var q=window.Arena3D.settings();st.textContent=q.musicOn?"♫":"♪";st.classList.toggle("off",!q.musicOn);se.textContent=q.sfxOn?"🔊":"🔇";se.classList.toggle("off",!q.sfxOn);}}
function click(e){var b=e.target.closest("[data-mg]");if(!b||!root.contains(b))return;var a=b.dataset.mg,i=Number(b.dataset.i),n=Number(b.dataset.n);if(a==="close"||a==="sort-back"){if(window.Arena3D)window.Arena3D.sfx(id,"back");close();if(window.Arena3D)window.Arena3D.stop();return;}if(a==="audio-music"){if(window.Arena3D){var q=window.Arena3D.settings();window.Arena3D.music(!q.musicOn,id);b.textContent=q.musicOn?"♪":"♫";b.classList.toggle("off",q.musicOn);}return;}if(a==="audio-sfx"){if(window.Arena3D){var q=window.Arena3D.settings();window.Arena3D.setSfx(!q.sfxOn);b.textContent=q.sfxOn?"🔇":"🔊";b.classList.toggle("off",q.sfxOn);}return;}if(window.Arena3D){var act=/reset|retry/.test(a)?"reset":/check|win|submit/.test(a)?"success":/tube|move|drop|cell|num|col/.test(a)?"move":/hint/.test(a)?"tap":"tap";window.Arena3D.sfx(id,act);}
if(id==="snake"){if(a==="snake-reset"){stop();snakeInit();}else if(a==="snake-start")snakeStart();else if(a.indexOf("snake-")===0)snakeTurn(a.slice(6));render();return;}
if(id==="backgammon"){if(a==="bg-reset")bgInit();else if(a==="bg-move"&&!s.done&&s.turn===0){var m={from:Number(b.dataset.from),to:Number(b.dataset.to),die:Number(b.dataset.die),enter:Number(b.dataset.from)===-1,off:Number(b.dataset.to)===-2,hit:false};var valid=bgMoves(0,m.die).find(function(x){return x.from===m.from&&x.to===m.to;});if(valid&&s.dice.indexOf(m.die)>=0){bgApply(0,valid);bgPlayTurn();}}render();return;}
if(id==="nonogram"){if(a==="nono-reset")nonoInit();else if(a==="nono-cell"&&!s.done){var nr=Math.floor(i/7),nc=i%7;s.board[nr][nc]=s.board[nr][nc]?0:1;}else if(a==="nono-check"){s.done=nonoCheck();if(s.done){s.msg="Tebrikler! Resmi doğru tamamladın.";localStorage.setItem("arenaNonoLevel",String(s.level+1));}else s.msg="Henüz doğru değil. Satır ve sütun ipuçlarını tekrar incele.";}render();return;}
if(id==="checkers"){if(a==="dama-reset")damaInit();else if(a==="dama-cell")damaHuman(i);render();return;}
if(id==="wordle"){if(a==="wordle-new")wordleInit();else if(a==="wordle-check"&&!s.done){var wi=root.querySelector("#mg-wordle"),guess=wordleNorm(wi&&wi.value);if(Array.from(guess).length!==5)s.msg="Tam 5 harf yazmalısın.";else if(WORDLE_ALLOWED.indexOf(guess)<0)s.msg="Bu kelime sözlüğümüzde yok. Başka kelime dene.";else{var marks=wordleMarks(guess,s.target);s.guesses.push({word:guess,marks:marks});if(guess===s.target){s.done=true;s.won=true;s.msg="Kelimeyi "+s.guesses.length+" denemede buldun!";}else if(s.guesses.length>=6){s.done=true;s.msg="Deneme hakkın bitti. Kelime: "+s.target;}else s.msg="Renk ipuçlarına göre yeni tahmin yap.";}}render();return;}
if(id==="ticTacToe"){if(a==="xo-reset")xoInit();else if(a==="xo-cell"&&!s.done&&!s.b[i]){s.b[i]="X";var w=xoWinner(s.b);if(w){s.done=true;s.msg=w==="draw"?"Berabere!":"Kazandın!";}else xoBot();}render();return;}
if(id==="connectFour"){if(a==="c4-reset")c4Init();else if(a==="c4-col"&&!s.done&&c4Drop(i,1)){s.moves++;var w=c4Winner(s.b);if(w){s.done=true;s.msg=w===1?"Kazandın!":"Berabere!";}else c4Bot();}render();return;}
if(id==="colorMemory"){cmAction(a,i);render();return;}if(id==="colorHunt"){chAction(a,i);render();return;}if(id==="minesweeper"){if(a==="mine-reset")mineInit();else if(a==="mine-flag")s.flagMode=!s.flagMode;else if(a==="mine-cell"){if(s.flagMode&&!s.open[i])s.flags[i]=!s.flags[i];else mineOpen(i);}render();return;}
if(id==="game2048"){if(a==="2048-reset")game2048Init();else if(a.indexOf("2048-")===0&&!s.done){game2048Move(a.slice(5));}render();return;}
if(id==="miniSudoku"){if(a==="sud-cell"&&s.blank.indexOf(i)>=0&&!s.done&&!s.pausedAt){s.sel=i;}else if(a==="sud-num"&&s.sel>=0&&!s.done&&!s.pausedAt){var v=n;if(s.pencil||s.quick){var arr=s.notes[s.sel],at=arr.indexOf(v);if(at>=0)arr.splice(at,1);else arr.push(v);}else{if(s.board[s.sel]!==v){s.history.push({board:s.board.slice(),notes:s.notes.map(x=>x.slice()),score:s.score,mistakes:s.mistakes});s.board[s.sel]=v;s.notes[s.sel]=[];if(v!==s.sol[s.sel])s.mistakes++;else s.score+=10;}}}else if(a==="sud-erase"&&s.sel>=0&&!s.done&&!s.pausedAt){s.history.push({board:s.board.slice(),notes:s.notes.map(x=>x.slice()),score:s.score,mistakes:s.mistakes});s.board[s.sel]=0;s.notes[s.sel]=[];}else if(a==="sud-undo"&&s.history.length&&!s.done){var prev=s.history.pop();s.board=prev.board;s.notes=prev.notes;s.score=prev.score;s.mistakes=prev.mistakes;}else if(a==="sud-pencil")s.pencil=!s.pencil;else if(a==="sud-quick")s.quick=!s.quick;else if(a==="sud-pause"){if(s.pausedAt){s.startedAt+=Date.now()-s.pausedAt;s.pausedAt=0;}else s.pausedAt=Date.now();}else if(a==="sud-hint"&&s.sel>=0&&!s.done&&!s.pausedAt){s.history.push({board:s.board.slice(),notes:s.notes.map(x=>x.slice()),score:s.score,mistakes:s.mistakes});s.board[s.sel]=s.sol[s.sel];s.notes[s.sel]=[];s.score=Math.max(0,s.score-5);s.msg="İpucu kullanıldı: doğru rakam yerleştirildi.";}else if(a==="sud-check"){s.done=sudValid();if(!s.done)s.mistakes++;s.msg=s.done?"Harika! Sudoku tamamlandı.":"Eksik veya çakışan hücre var. Satır, sütun ve kutuları kontrol et.";if(s.done){localStorage.setItem("arenaSudokuLevel",String(s.level+1));s.msg="Seviye "+s.level+" tamamlandı! Sonraki seviye açıldı.";}}else if(a==="sud-reset")sudInit();if(s.mistakes>=3&&!s.done)s.msg="3 hata hakkın doldu. Yeniden başlatabilirsin.";render();return;}
if(id==="memory"){if(a==="mem-reset")memInit();else if(a==="mem-card"&&!s.lock&&!s.done&&s.doneCards.indexOf(i)<0&&s.open.indexOf(i)<0){s.open.push(i);if(s.open.length===2){s.moves++;var x=s.open[0],y=s.open[1];if(s.deck[x]===s.deck[y]){s.doneCards.push(x,y);s.open=[];if(s.doneCards.length===16)s.done=true;}else{s.lock=true;render();later(function(){s.open=[];s.lock=false;render();},800);return;}}}render();return;}
if(id==="colorSort"||id==="liquidSort"||id==="ballSort"){sortAction(a,i);render();if(a==="sort-tube")sortPlayMoveFx();return;}
if(id==="reflexTap"){if(a==="reflex-reset"){stop();reflexInit();}else if(a==="reflex-tap"){if(["idle","early","result"].indexOf(s.phase)>=0){stop();s.phase="waiting";s.msg="Yeşil olana kadar dokunma!";render();later(function(){if(s&&s.phase==="waiting"){s.phase="ready";s.readyAt=performance.now();s.msg="Şimdi!";render();}},1200+Math.random()*3000);}else if(s.phase==="waiting"){stop();s.phase="early";s.msg="Erken dokundun. Tekrar dene.";render();}else if(s.phase==="ready"){s.ms=Math.round(performance.now()-s.readyAt);s.phase="result";if(!s.best||s.ms<s.best){s.best=s.ms;localStorage.setItem("arenaReflexBest",String(s.best));}s.msg=s.ms<250?"Çok hızlı!":s.ms<400?"İyi refleks!":"Biraz daha hızlanabilirsin.";render();}}return;}
if(id==="wordScramble"){if(a==="word-reset")wordInit();else if(a==="word-check"){var wi=root.querySelector("#mg-word"),v=wi?wi.value.trim().toLocaleUpperCase("tr-TR").replace(/\s+/g,""):"";if(v===WORDS[s.idx][0]){s.score+=10;s.idx++;if(s.idx>=WORDS.length)s.done=true;else s.letters=scramble(WORDS[s.idx][0]);s.msg="Doğru!";}else s.msg="Tekrar dene.";}render();return;}
if(id==="mathSprint"){if(a==="math-reset"){stop();mathInit();}else if(a==="math-start"&&!s.running){s.running=true;render();every(function(){if(!s||id!=="mathSprint")return;s.sec--;var t=root.querySelector(".mg-timer");if(t)t.textContent=s.sec;if(s.sec<=0){stop();s.done=true;s.running=false;render();}},1000);}else if(a==="math-key"&&s.running){var mi=root.querySelector("#mg-math");if(mi){mi.value+=String(n);mi.focus({preventScroll:true});}}else if(a==="math-back"&&s.running){var mi2=root.querySelector("#mg-math");if(mi2){mi2.value=mi2.value.slice(0,-1);mi2.focus({preventScroll:true});}}else if(a==="math-check"&&s.running){var mi3=root.querySelector("#mg-math"),v=mi3&&mi3.value!==""?Number(mi3.value):NaN;if(!Number.isFinite(v)){if(mi3)mi3.focus({preventScroll:true});return;}if(v===s.ans){s.score+=10;s.correct++;s.msg="Doğru!";}else{s.score=Math.max(0,s.score-2);s.msg="Yanlış.";}mathQ();render();}return;}}
function close(){stop();if(root){root.classList.remove("open");root.innerHTML="";}id="";s=null;window.dispatchEvent(new Event("arena:home"));}
function open(k){if(!G[k])return false;ensure();stop();id=k;if(k==="snake")snakeInit();else if(k==="backgammon")bgInit();else if(k==="nonogram")nonoInit();else if(k==="checkers")damaInit();else if(k==="wordle")wordleInit();else if(k==="ticTacToe")xoInit();else if(k==="connectFour")c4Init();else if(k==="minesweeper")mineInit();else if(k==="colorMemory")cmInit();else if(k==="colorHunt")chInit();else if(k==="game2048")game2048Init();else if(k==="miniSudoku")sudInit();else if(k==="memory")memInit();else if(k==="colorSort"||k==="liquidSort"||k==="ballSort")colorInit();else if(k==="reflexTap")reflexInit();else if(k==="wordScramble")wordInit();else if(k==="mathSprint")mathInit();root.classList.add("open");render();if(k==="colorMemory")cmShow();return true;}
